effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bool u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
bvec4 u_xlatb4;
vec4 u_xlat5;
bool u_xlatb6;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1 = texture(EchoBuff, acScreenNorm.xy);
    if(int(_blend) == 0) {
        fragColor = u_xlat0 * vec4(_opacity) + u_xlat1;
    } else {
        u_xlatb2 = int(_blend)==1;
        if(u_xlatb2){
            u_xlatb2 = 0<int(_frame);
            u_xlat3 = max(u_xlat0, u_xlat1);
            fragColor = (bool(u_xlatb2)) ? u_xlat3 : u_xlat0;
        } else {
            u_xlatb2 = int(_blend)==2;
            if(u_xlatb2){
                u_xlatb2 = 0<int(_frame);
                u_xlat3 = min(u_xlat0, u_xlat1);
                fragColor = (bool(u_xlatb2)) ? u_xlat3 : u_xlat0;
            } else {
                u_xlat2 = u_xlat0 * vec4(_opacity);
                u_xlat3 = (-u_xlat0) * vec4(_opacity) + vec4(1.0, 1.0, 1.0, 1.0);
                u_xlat4 = (-u_xlat1) + vec4(1.0, 1.0, 1.0, 1.0);
                u_xlat3 = (-u_xlat3) * u_xlat4 + vec4(1.0, 1.0, 1.0, 1.0);
                u_xlat4.x = (-_opacity) + 1.0;
                u_xlat5 = u_xlat1 * vec4(_opacity);
                u_xlat5 = u_xlat0 * u_xlat4.xxxx + u_xlat5;
                u_xlat2 = u_xlat1 * u_xlat4.xxxx + u_xlat2;
                u_xlatb4 = equal(ivec4(ivec4(int(_blend), int(_blend), int(_blend), int(_blend))), ivec4(3, 4, 5, 6));
                u_xlatb6 = 0<int(_frame);
                u_xlat1 = u_xlat0 + u_xlat1;
                u_xlat1 = u_xlat1 * vec4(0.5, 0.5, 0.5, 0.5);
                u_xlat0 = (bool(u_xlatb6)) ? u_xlat1 : u_xlat0;
                u_xlat0 = u_xlatb4.w ? u_xlat0 : vec4(0.0, 0.0, 0.0, 0.0);
                u_xlat0 = (u_xlatb4.z) ? u_xlat2 : u_xlat0;
                u_xlat0 = (u_xlatb4.y) ? u_xlat5 : u_xlat0;
                fragColor = (u_xlatb4.x) ? u_xlat3 : u_xlat0;
            }
        }
    }
    return;
}
